#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class WorldBossRailGeometryConsumerTests {
  static JObject Fixture()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/world-boss-geometry-fixtures-20261002.json"));
  static JObject Traces()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/WorldBossRail-20261002/GeometryConsumer/server-bind-traces.json"));
  static JObject Case(int i)=>(JObject)Traces()["cases"][i];
  static Func<RailConsistMotion> Factory(JObject c){var g=(JObject)c["acceptedGeometry"];var p=(JObject)g["profile"].DeepClone();var first=(JObject)g["initial"].DeepClone();return()=>new RailConsistMotion(new MainlineDetourPath(p),first,2000,4000);}
  static WorldBossRailGeometryConsumer Open(JObject c)=>new WorldBossRailGeometryConsumer(new WorldBossRailSnapshot((JObject)c["before"],(JObject)c["before"]["definition"],(string)c["before"]["attemptId"]),"a",(JObject)c["acceptedGeometry"]["profile"],Factory(c));
  static void Start(WorldBossRailGeometryConsumer consumer,JObject c){if(c["receipt"].Type==JTokenType.Null){consumer.ApplyAuthority((JObject)c["acceptedRail"],(JObject)c["acceptedGeometry"]);return;}consumer.PreviewRoute("p1r1",(string)c["name"]);Assert.IsTrue(JToken.DeepEquals(c["body"],consumer.ConfirmPreview("route")));Assert.AreEqual("ENTRY",consumer.SelectedPath);consumer.AcceptReceipt((JObject)c["receipt"],(JObject)c["acceptedRail"],(JObject)c["acceptedGeometry"]);}
  static void Finish(WorldBossRailGeometryConsumer consumer,JObject c){consumer.Advance(5500);consumer.ApplyAuthority((JObject)c["finalRail"],(JObject)c["finalGeometry"],(JObject)c["bound"]);}
  [Test] public void GeometryReceiptConsumerMustExist(){Assert.NotNull(typeof(RailConsistMotion).Assembly.GetType("LastRail.Battle.WorldBossRailGeometryConsumer"));}
  [Test] public void MaximumEscapedAttemptRoundNamespaceRemainsValid(){var p=(JObject)Fixture()["cases"][0]["snapshot"]["profile"].DeepClone();p["geometryRef"]=new JArray(new string('\u0001',200),new string('\u0001',200)).ToString(Newtonsoft.Json.Formatting.None);Assert.AreEqual(2407,((string)p["geometryRef"]).Length);Assert.DoesNotThrow(()=>new MainlineDetourPath(p));}
  [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)]
  public void FrozenEightAuthorityGeometrySnapshotsRemainExact(int i){var g=(JObject)Fixture()["cases"][i]["snapshot"];var replica=new WorldBossRailGeometrySnapshot(g,(JObject)g["profile"]);Assert.IsTrue(JToken.DeepEquals(g,replica.Capture()));var copy=replica.Capture();copy["sample"]["headDistanceMm"]=0;Assert.IsTrue(JToken.DeepEquals(g,replica.Capture()));}
  [TestCase(0)][TestCase(1)][TestCase(2)] public void ThreeOriginalReceiptResultBindingsAndRestoresRemainExact(int i){var c=Case(i);using var consumer=Open(c);int commands=0,samples=0;consumer.Bind(_=>commands++,_=>samples++,null);Start(consumer,c);Finish(consumer,c);Assert.AreEqual(i==0?0:1,commands);Assert.AreEqual(6,samples);Assert.IsTrue(JToken.DeepEquals(c["bound"],consumer.BoundResult));Assert.IsTrue(JToken.DeepEquals(c["finalGeometry"],consumer.Geometry.Capture()));Assert.AreEqual((string)c["name"],consumer.SelectedPath);var restore=WorldBossRailGeometryConsumer.RestoreLocal(consumer.CaptureLocal(),consumer.Rail.Definition,consumer.Rail.AttemptId,"a",(JObject)c["acceptedGeometry"]["profile"],Factory(c));Assert.IsTrue(restore.AwaitingAuthorityRefresh);Assert.Throws<InvalidOperationException>(()=>restore.Advance(1));restore.ApplyAuthority((JObject)c["finalRail"],(JObject)c["finalGeometry"],(JObject)c["bound"]);Assert.IsFalse(restore.AwaitingAuthorityRefresh);Assert.IsTrue(JToken.DeepEquals(c["bound"],restore.BoundResult));restore.Dispose();}
  [Test] public void LateOriginalReceiptReplaysAtOriginalTimestampWithoutSecondCommand(){var c=Case(2);using var consumer=Open(c);int commands=0;consumer.Bind(_=>commands++,null,null);consumer.PreviewRoute("p1r1","RIGHT");consumer.ConfirmPreview("route");consumer.Advance(1000);Assert.AreEqual("ENTRY",consumer.SelectedPath);consumer.AcceptReceipt((JObject)c["receipt"],(JObject)c["acceptedRail"],(JObject)c["acceptedGeometry"]);Assert.AreEqual("RIGHT",consumer.SelectedPath);Assert.AreEqual(11000,(long)consumer.ReadSample()["atMs"]);consumer.Advance(4500);consumer.ApplyAuthority((JObject)c["finalRail"],(JObject)c["finalGeometry"],(JObject)c["bound"]);Assert.AreEqual(1,commands);Assert.IsTrue(JToken.DeepEquals(c["bound"],consumer.BoundResult));}
  [Test] public void OriginalReceiptDuplicateAndSameAuthorityReplayDoNotNotifyOrIssueInput(){var c=Case(2);using var consumer=Open(c);Start(consumer,c);int n=0;consumer.Bind(_=>n++,null,()=>n++);var before=consumer.CaptureLocal();consumer.AcceptReceipt((JObject)c["receipt"],(JObject)c["acceptedRail"],(JObject)c["acceptedGeometry"]);Assert.AreEqual(before,consumer.CaptureLocal());Assert.AreEqual(0,n);}
  [Test] public void PendingCheckpointKeepsOriginalAndCanReconcileAfterRestore(){var c=Case(2);using var consumer=Open(c);consumer.PreviewRoute("p1r1","RIGHT");consumer.ConfirmPreview("route");var r=WorldBossRailGeometryConsumer.RestoreLocal(consumer.CaptureLocal(),consumer.Rail.Definition,consumer.Rail.AttemptId,"a",(JObject)c["acceptedGeometry"]["profile"],Factory(c));Assert.IsTrue(JToken.DeepEquals(c["body"],r.OriginalForReconciliation()));Assert.Throws<InvalidOperationException>(()=>r.ConfirmPreview("new"));r.AcceptReceipt((JObject)c["receipt"],(JObject)c["acceptedRail"],(JObject)c["acceptedGeometry"]);Assert.IsNull(r.Pending);Assert.AreEqual("RIGHT",r.SelectedPath);r.Dispose();}
  [Test] public void BindReplacementUnbindAndDisposeRespectCallbackOwnership(){var c=Case(2);var consumer=Open(c);int first=0,second=0,changes=0;consumer.Bind(_=>first++,null,null);consumer.Bind(_=>second++,null,()=>changes++);Start(consumer,c);Assert.AreEqual(0,first);Assert.AreEqual(1,second);consumer.Unbind();int old=changes;consumer.Advance(5500);Assert.AreEqual(old,changes);consumer.Dispose();consumer.Dispose();Assert.Throws<ObjectDisposedException>(()=>consumer.ApplyAuthority((JObject)c["finalRail"],(JObject)c["finalGeometry"],(JObject)c["bound"]));Assert.AreEqual(1,second);}
  [Test] public void CallbackDetachPreventsSubsequentCallbacksAndLateReply(){var c=Case(2);var consumer=Open(c);int commands=0,changes=0;consumer.Bind(_=>{commands++;consumer.Dispose();},null,()=>changes++);consumer.PreviewRoute("p1r1","RIGHT");int prior=changes;consumer.ConfirmPreview("route");Assert.AreEqual(1,commands);Assert.AreEqual(prior,changes);Assert.Throws<ObjectDisposedException>(()=>consumer.AcceptReceipt((JObject)c["receipt"],(JObject)c["acceptedRail"],(JObject)c["acceptedGeometry"]));}
  [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)]
  public void ActualSourceRejectionsCannotPartiallyPublish(int i){var c=Case(2);using var consumer=Open(c);Start(consumer,c);consumer.Advance(5500);var before=consumer.CaptureLocal();var bad=Traces()["rejectionCases"][i];Assert.IsNotEmpty((string)bad["error"]);Assert.Throws<ArgumentException>(()=>consumer.ApplyAuthority((JObject)bad["rail"],(JObject)bad["geometry"],(JObject)c["bound"]));Assert.AreEqual(before,consumer.CaptureLocal());}
  [Test] public void WrongReceiptSelectionTimeKeepsPendingAndMotionUnconfirmed(){var c=Case(2);using var consumer=Open(c);consumer.PreviewRoute("p1r1","RIGHT");consumer.ConfirmPreview("route");var s=(JObject)c["acceptedRail"].DeepClone();var receipt=(JObject)c["receipt"].DeepClone();receipt["acceptedAt"]=9999;s["receipts"][0]["receipt"]=receipt;var before=consumer.CaptureLocal();Assert.Throws<ArgumentException>(()=>consumer.AcceptReceipt(receipt,s,(JObject)c["acceptedGeometry"]));Assert.AreEqual(before,consumer.CaptureLocal());Assert.AreEqual("ENTRY",consumer.SelectedPath);Assert.IsNotNull(consumer.Pending);}
  [Test] public void LocomotiveMergeDoesNotPermitNextBranchButLastTailDoes(){var c=Case(2);using var consumer=Open(c);Start(consumer,c);Finish(consumer,c);Assert.IsFalse(consumer.NextBranchPermitted);Assert.Throws<InvalidOperationException>(()=>consumer.PreviewRoute("p1r2","RIGHT"));consumer.Advance(1500);Assert.IsFalse(consumer.NextBranchPermitted,"Local rear alone is not authority evidence");consumer.ApplyAuthority((JObject)c["finalRail"],(JObject)c["tailGeometry"],(JObject)c["tailBound"]);Assert.IsTrue(consumer.NextBranchPermitted);Assert.AreEqual("TAIL_MERGE",(string)consumer.Geometry.Capture()["events"].Last["kind"]);}
  [Test] public void BoundEvidenceAndCachedRestoreTamperingCannotChangeOriginalResult(){var c=Case(2);using var consumer=Open(c);Start(consumer,c);consumer.Advance(5500);var b=(JObject)c["bound"].DeepClone();b["result"]["outcome"]="FAILURE";var before=consumer.CaptureLocal();Assert.Throws<ArgumentException>(()=>consumer.ApplyAuthority((JObject)c["finalRail"],(JObject)c["finalGeometry"],b));Assert.AreEqual(before,consumer.CaptureLocal());consumer.ApplyAuthority((JObject)c["finalRail"],(JObject)c["finalGeometry"],(JObject)c["bound"]);var saved=JObject.Parse(consumer.CaptureLocal());saved["motion"]["sample"]["actualMmPerSecond"]=1;Assert.Throws<ArgumentException>(()=>WorldBossRailGeometryConsumer.RestoreLocal(saved.ToString(),consumer.Rail.Definition,consumer.Rail.AttemptId,"a",(JObject)c["acceptedGeometry"]["profile"],Factory(c)));}
  [Test] public void NestedSampleAdvanceCannotPublishOutOfOrder(){var c=Case(2);using var consumer=Open(c);Start(consumer,c);var received=new System.Collections.Generic.List<long>();bool attempted=false,rejected=false;consumer.Bind(null,sample=>{received.Add((long)sample["sequence"]);if(!attempted){attempted=true;try{consumer.Advance(1);}catch(InvalidOperationException){rejected=true;}}},null);consumer.Advance(2000);CollectionAssert.AreEqual(new long[]{1,2},received);Assert.IsTrue(rejected);Assert.AreEqual(12000,(long)consumer.ReadSample()["atMs"]);}
  [Test] public void WindowPartialSafetyNeverBecomesCompleteSupport(){var w=Fixture()["window"];var original=new WorldBossRailTraversalEvidence((JObject)w["original"]);Assert.IsTrue(original.ImpactSupported);Assert.IsFalse(original.Supported);CollectionAssert.Contains(((JArray)original.Capture()["reasons"]).Select(x=>(string)x),"PATH_ENVELOPE_EXHAUSTED");var extended=new WorldBossRailTraversalEvidence((JObject)w["extended"]);Assert.IsTrue(extended.Supported);Assert.IsTrue(extended.ImpactSupported);var safe=extended.Capture()["safeHeadWindows"][0];Assert.AreEqual(22613,(long)safe["earliestImpactAtMs"]);Assert.AreEqual(30724,(long)safe["latestImpactAtMs"]);Assert.IsFalse(new WorldBossRailTraversalEvidence((JObject)w["zeroSpeed"]).Supported);Assert.IsFalse(new WorldBossRailTraversalEvidence((JObject)w["referenceMismatch"]).Supported);}
 }
}
#endif

